function parseMonthlyCode(code){if(!/^[0-9]{2,7}$/.test(code))return {error:'Введите код: первая цифра — тип, остальные — полигон (например, 212).'};const type=S.workflow.types.find(t=>t.code===code[0]),polygon=S.monthlyCatalog.polygons.find(p=>p.number===Number(code.slice(1)));return !type||!polygon?{error:'Тип занятости или полигон с таким номером не найден.'}:{type,polygon};}
async function monthlyCellChange(rowId,day,entry){
 if(S.busy)return;S.busy=true;try{
 const cells=rowId?[{rowId,day}]:monthlyTargets(),revision=S.cellEditor?.baseRevision??S.workflow.revision;
 S.workflow=await api(monthlyPath('/cells'),'PUT',{cells,entry,expectedRevision:revision});S.cellEditor=null;renderMonthlyKeep();toast('Сохранено ячеек: '+cells.length);
 }catch(e){if(e.status===409){S.cellEditor=null;renderMonthlyKeep();await refreshMonthly();}throw e;}finally{S.busy=false;}
}
function monthlyDraftChanged(){const ed=S.cellEditor;if(!ed)return false;const entry=S.workflow.rows.find(r=>r.id===ed.rowId)?.cells[String(ed.day)];return ed.code!==(entry?entry.typeCode+String(entry.polygonNumber):'')||ed.draft.workId!==(entry?.workId||'');}
async function monthlyApprove(){
 if(S.busy)return;if(monthlyStage()!=='verification')return;if(monthlyDraftChanged())return toast('Сначала сохраните изменения ячейки или закройте редактор',true);const cells=monthlyTargets();if(!cells.length)return toast('Выберите заполненные ячейки',true);S.busy=true;
 try{S.workflow=await api(monthlyPath('/approvals'),'POST',{cells,expectedRevision:S.cellEditor?.baseRevision??S.workflow.revision});S.cellEditor=null;renderMonthlyKeep();toast('Подтверждено ячеек: '+cells.length);}catch(e){if(e.status===409){S.cellEditor=null;renderMonthlyKeep();await refreshMonthly();}throw e;}finally{S.busy=false;}
}
function monthlySelectionActions(){return S.selectedCells.size?btn('monthly-selection-clear','Снять выделение','close')+(S.workflow.stage!=='approved'&&monthlyStage()==='verification'?btn('monthly-approve-selected','Подтвердить выбранные','check'):''):'';}
function monthlyRangeCells(start,end){const rows=S.workflow.rows,a=rows.findIndex(r=>r.id===start.rowId),b=rows.findIndex(r=>r.id===end.rowId),cells=[];if(a<0||b<0)return cells;for(let i=Math.min(a,b);i<=Math.max(a,b);i++)for(let day=Math.min(start.day,end.day);day<=Math.max(start.day,end.day);day++)if(!S.workflow.calendar.nonworking.includes(day))cells.push(rows[i].id+':'+day);return cells;}
function paintMonthlySelection(){document.querySelectorAll('.monthly-day[data-row]').forEach(el=>{const selected=S.selectedCells.has(el.dataset.row+':'+el.dataset.day);el.closest('td').classList.toggle('cell-selected',selected);el.setAttribute('aria-selected',String(selected));});const count=document.querySelector('#monthly-selection-count'),actions=document.querySelector('#monthly-selection-actions');if(count)count.textContent=String(S.selectedCells.size);if(actions)actions.innerHTML=monthlySelectionActions();}
function closeMonthlyEditorForSelection(){
 if(!S.cellEditor)return;const old=S.cellEditor;S.cellEditor=null;
 const input=document.querySelector('.monthly-code-input');if(input){const row=S.workflow.rows.find(r=>r.id===old.rowId),entry=row?.cells[String(old.day)];const button=document.createElement('button');button.type='button';button.className='monthly-day';button.dataset.action='monthly-cell';button.dataset.row=old.rowId;button.dataset.day=String(old.day);button.textContent=entry?entry.typeCode+String(entry.polygonNumber):'';button.setAttribute('aria-label',row.employeeSnapshot.name+', день '+old.day);input.replaceWith(button);}
 document.querySelector('.monthly-editor')?.remove();document.querySelector('.monthly-workspace')?.classList.remove('with-editor');
}
function monthlyToggleSelection(cell){if(S.busy)return;closeMonthlyEditorForSelection();const key=cell.dataset.row+':'+cell.dataset.day;if(S.selectedCells.has(key))S.selectedCells.delete(key);else S.selectedCells.add(key);paintMonthlySelection();}
let monthlyGesture=null,monthlyIgnoreClick=false;
function monthlyEventCell(target,allowOff=false){const cell=target?.closest?.('.monthly-day[data-row]');return cell&&S.view==='workflow'&&S.workflow?.format==='monthly-v2'&&(!cell.disabled||allowOff)?cell:null;}
document.addEventListener('pointerdown',e=>{
 const cell=monthlyEventCell(e.target);if(!cell||cell.matches('input')||e.button!==0||S.busy)return;
 monthlyGesture={start:{rowId:cell.dataset.row,day:Number(cell.dataset.day)},x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,dragged:false,base:e.ctrlKey?new Set(S.selectedCells):new Set(),capture:cell,pointerId:e.pointerId};
 if(Number.isInteger(e.pointerId))cell.setPointerCapture?.(e.pointerId);
});
function monthlyDragFrame(){const g=monthlyGesture;if(!g?.dragged)return;const scroll=document.querySelector('.monthly-scroll');if(!scroll)return;const r=scroll.getBoundingClientRect(),frozen=scroll.querySelector(window.matchMedia('(min-width:901px)').matches?'tbody td:nth-child(4)':'tbody td:nth-child(3)'),dataLeft=Math.min(r.right-4,Math.max(r.left,frozen?.getBoundingClientRect().right||r.left)),headerBottom=scroll.querySelector('thead')?.getBoundingClientRect().bottom||r.top,x=Math.max(dataLeft+2,Math.min(r.right-2,g.lastX)),y=Math.max(headerBottom+2,Math.min(r.bottom-2,g.lastY));
 if(g.lastX>r.right-20)scroll.scrollLeft+=12;else if(g.lastX<dataLeft+20)scroll.scrollLeft-=12;
 if(g.lastY>r.bottom-20)scroll.scrollTop+=12;else if(g.lastY<headerBottom+20)scroll.scrollTop-=12;
 const cell=monthlyEventCell(document.elementFromPoint(x,y),true);if(cell&&!cell.matches('input')){S.selectedCells=new Set([...g.base,...monthlyRangeCells(g.start,{rowId:cell.dataset.row,day:Number(cell.dataset.day)})]);paintMonthlySelection();}
 requestAnimationFrame(monthlyDragFrame);
}
document.addEventListener('pointermove',e=>{const g=monthlyGesture;if(!g)return;g.lastX=e.clientX;g.lastY=e.clientY;if(!g.dragged&&Math.hypot(e.clientX-g.x,e.clientY-g.y)>5){g.dragged=true;closeMonthlyEditorForSelection();monthlyDragFrame();}});
document.addEventListener('pointerup',()=>{if(Number.isInteger(monthlyGesture?.pointerId))monthlyGesture.capture.releasePointerCapture?.(monthlyGesture.pointerId);if(monthlyGesture?.dragged){monthlyIgnoreClick=true;paintMonthlySelection();setTimeout(()=>monthlyIgnoreClick=false,0);}monthlyGesture=null;});
document.addEventListener('pointercancel',()=>{monthlyGesture=null;});
window.addEventListener('blur',()=>{monthlyGesture=null;});
document.addEventListener('click',e=>{const cell=monthlyEventCell(e.target);if(!cell||cell.matches('input')||e.detail===0)return;if(monthlyIgnoreClick)return;monthlyToggleSelection(cell);});
document.addEventListener('dblclick',e=>{const cell=monthlyEventCell(e.target);if(!cell||cell.matches('input')||S.busy)return;e.preventDefault();monthlyCellForm(cell.dataset.row,Number(cell.dataset.day));});
document.addEventListener('contextmenu',e=>{const cell=monthlyEventCell(e.target);if(!cell)return;e.preventDefault();if(S.busy||cell.matches('input'))return;monthlyCellForm(cell.dataset.row,Number(cell.dataset.day));});
document.addEventListener('keydown',async e=>{if(!['Backspace','Delete'].includes(e.key)||S.view!=='workflow'||S.workflow?.format!=='monthly-v2'||e.target.matches?.('input,textarea,select,[contenteditable="true"]')||modal.open||picker.open||!S.selectedCells.size)return;e.preventDefault();if(!monthlyCanEdit())return toast('Нет права изменять эту таблицу',true);try{await monthlyCellChange(null,null,null);}catch(error){toast(error.message,true);}});
async function refreshMonthly(){if(S.view!=='workflow'||S.workflow?.format!=='monthly-v2')return;const id=S.workflow.id,stage=monthlyStage(),doc=await api(monthlyPath(''));if(monthlyGesture)return;if(S.view!=='workflow'||S.workflow?.id!==id||monthlyStage()!==stage)return;if(doc.revision>S.workflow.revision){
 const active=document.activeElement,isInput=active?.classList?.contains('monthly-code-input'),selection=isInput?[active.selectionStart,active.selectionEnd]:null;
 S.workflow=doc;if(doc.stage==='approved')S.cellEditor=null;renderMonthlyKeep();
 if(isInput){const input=document.querySelector('.monthly-code-input');if(input){input.focus({preventScroll:true});input.setSelectionRange(...selection);}}
 const status=document.querySelector('#monthly-sync');if(status)status.textContent=S.cellEditor?'Таблица обновлена. Перед сохранением заново откройте день.':'Изменения синхронизированы';
 }}
async function monthlySyncLoop(){try{if(S.user&&!S.busy&&!monthlyGesture){if(S.view==='workflow'&&S.workflow?.format==='monthly-v2')await refreshMonthly();else if(flowStages.includes(S.view)||S.view==='home'){const view=S.view;const docs=await api('/workflows');if(S.view===view){S.workflows=docs;renderPage();}}}}catch(e){const status=document.querySelector('#monthly-sync');if(status)status.textContent='Нет обновлений: '+e.message;}finally{setTimeout(monthlySyncLoop,3000);}}
async function downloadWorkbook(path,name){const r=await fetch(API_ROOT+path);if(!r.ok){const data=await r.json();throw new Error(data.error||'Ошибка выгрузки');}const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),15000);}

init();
